{
  "task_summary": "Predict whether a diabetes hospital encounter will end in readmission, using encounter history, severity, and treatment-related signals that should generalize across domains.",
  "scores": [
    {
      "feature_id": 0,
      "score": 0.08,
      "rationale": "Demographic signal may correlate with care patterns, but is a weak and potentially brittle shortcut."
    },
    {
      "feature_id": 1,
      "score": 0.05,
      "rationale": "Mostly a proxy for population mix and care differences; limited stable causal relevance."
    },
    {
