      "rationale": "Often missing and weakly informative; can reflect data collection artifacts more than stable risk."
    },
    {
      "feature_id": 4,
      "score": 0.12,
      "rationale": "Admission type reflects acuity and planned vs emergency care, which can generalize moderately well."
    },
    {
      "feature_id": 5,
      "score": 0.28,
      "rationale": "Discharge disposition is strongly tied to post-acute support and near-term readmission risk."
    },
    {
      "feature_id": 6,
      "score": 0.16,
      "rationale": "Longer stays usually indicate greater severity or complications, useful beyond the source domain."
    },
